-- name: LeaderboardQueueDiagnostics :many
SELECT 'runs'::text AS family,count(*)::bigint AS pending,count(*) FILTER(WHERE process_after<=statement_timestamp() AND retry_after<=statement_timestamp() AND (locked_until IS NULL OR locked_until<=statement_timestamp()))::bigint AS due,count(*) FILTER(WHERE locked_until>statement_timestamp())::bigint AS claimed,count(*) FILTER(WHERE retry_after>statement_timestamp())::bigint AS retrying,min(dirtied_at)::timestamptz AS oldest_pending_at,min(process_after) FILTER(WHERE process_after<=statement_timestamp() AND retry_after<=statement_timestamp() AND (locked_until IS NULL OR locked_until<=statement_timestamp()))::timestamptz AS oldest_due_at FROM leaderboard_dirty_runs WHERE tenant_id= @tenant_id::uuid
UNION ALL
