-- name: ListLeaderboardMetricTenants :many
SELECT id FROM tenants WHERE id> @after_id::uuid ORDER BY id LIMIT 100;

-- name: LeaderboardMetricOperationProgress :many
SELECT phase,state,discovered,last_progress_at FROM leaderboard_operations
WHERE tenant_id= @tenant_id::uuid ORDER BY started_at DESC,id LIMIT 1;
